// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Account secrets as refs: read the account book from user-acct.json in the secrets folder (never from the command line, never stored by fb)
// Flo: expand the secrets folder > read user-acct.json {"v":1,"main":id,"accs":[{id,login,pass,...}]} or the old flat file (= one account "main") > check ids, count, limit > pick one account > `fb secret` lists ids and which fields are set, never the values
// I/O: folder path + limit (caller) > Book (arena owned); errors BadConfig (broken file, bad or duplicate id, too many accounts)
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .file = "user-acct.json", .maxz = 65536, .idmx = 16, .main = "main" };
const FIELDS = [_][]const u8{ "login", "pass", "newp", "firs", "last", "mail", "birt" };
pub const Acc = struct { id: []const u8 = CF.main, login: []const u8 = "", pass: []const u8 = "", newp: []const u8 = "", firs: []const u8 = "", last: []const u8 = "", mail: []const u8 = "", birt: []const u8 = "", lang: []const u8 = "", scal: u32 = 100 };
const Raw = struct { v: u32 = 1, main: []const u8 = "", accs: []const Acc = &.{}, login: []const u8 = "", pass: []const u8 = "", newp: []const u8 = "", firs: []const u8 = "", last: []const u8 = "", mail: []const u8 = "", birt: []const u8 = "", lang: []const u8 = "", scal: u32 = 100 };
pub const Book = struct { main: []const u8, accs: []const Acc, filez: bool };
pub fn dirOf(allo: std.mem.Allocator, home: []const u8, conf: cfgz.Conf) ![]u8 { return cfgz.pathExpa(allo, home, conf.secr_loca_main); }
pub fn idOk(id: []const u8) bool { if (id.len == 0 or id.len > CF.idmx) return false; for (id) |chr| { if (!(std.ascii.isLower(chr) or std.ascii.isDigit(chr) or chr == '-')) return false; } return true; }
pub fn toSecr(acc: Acc) task.Secr { return .{ .login = acc.login, .pass = acc.pass, .newp = acc.newp, .firs = acc.firs, .last = acc.last, .mail = acc.mail, .birt = acc.birt }; }
pub fn loadBook(aren: std.mem.Allocator, iozz: std.Io, dir: []const u8, limit: u32) !Book { const none: Book = .{ .main = CF.main, .accs = &.{.{}}, .filez = false }; if (dir.len == 0) return none; const path = std.fs.path.join(aren, &.{ dir, CF.file }) catch return none; const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, aren, .limited(CF.maxz)) catch return none; const raw = std.json.parseFromSliceLeaky(Raw, aren, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadConfig;
if (raw.accs.len == 0) { const one = try aren.alloc(Acc, 1); one[0] = .{ .id = CF.main, .login = raw.login, .pass = raw.pass, .newp = raw.newp, .firs = raw.firs, .last = raw.last, .mail = raw.mail, .birt = raw.birt, .lang = raw.lang, .scal = raw.scal }; return .{ .main = CF.main, .accs = one, .filez = true }; }
if (raw.accs.len > limit) return error.BadConfig; for (raw.accs, 0..) |acc, ix| { if (!idOk(acc.id) or acc.scal == 0 or acc.scal > 100) return error.BadConfig; for (raw.accs[0..ix]) |prev| { if (std.mem.eql(u8, prev.id, acc.id)) return error.BadConfig; } } const mn = if (raw.main.len > 0) raw.main else raw.accs[0].id; var hit = false; for (raw.accs) |acc| { if (std.mem.eql(u8, acc.id, mn)) hit = true; } if (!hit) return error.BadConfig; return .{ .main = mn, .accs = raw.accs, .filez = true }; }
pub fn pick(book: Book, id: []const u8) ?Acc { const want = if (id.len == 0) book.main else id; for (book.accs) |acc| { if (std.mem.eql(u8, acc.id, want)) return acc; } return null; }
fn setOf(sc: Acc, name: []const u8) bool { if (std.mem.eql(u8, name, "login")) return sc.login.len > 0; if (std.mem.eql(u8, name, "pass")) return sc.pass.len > 0; if (std.mem.eql(u8, name, "newp")) return sc.newp.len > 0; if (std.mem.eql(u8, name, "firs")) return sc.firs.len > 0; if (std.mem.eql(u8, name, "last")) return sc.last.len > 0; if (std.mem.eql(u8, name, "mail")) return sc.mail.len > 0; return sc.birt.len > 0; }
pub fn count(sc: task.Secr) u32 { const acc: Acc = .{ .login = sc.login, .pass = sc.pass, .newp = sc.newp, .firs = sc.firs, .last = sc.last, .mail = sc.mail, .birt = sc.birt }; return countAcc(acc); }
pub fn countAcc(acc: Acc) u32 { var cnt: u32 = 0; for (FIELDS) |nm| { if (setOf(acc, nm)) cnt += 1; } return cnt; }
pub fn status(ctx: *task.Ctx, dir: []const u8, json: bool) void { const book = loadBook(ctx.aren, ctx.iozz, dir, ctx.conf.acct_maxx_coun) catch { task.say(ctx, "{s} is broken: check the JSON, ids (a-z 0-9 -, max 16, no repeats), main, scal 1-100 and at most {d} accounts", .{ CF.file, ctx.conf.acct_maxx_coun }); return; };
if (json) { var out: std.ArrayList(u8) = .empty; for (book.accs, 0..) |acc, ix| { const row = std.fmt.allocPrint(ctx.aren, "{s}{{\"id\":\"{s}\",\"set\":{d},\"of\":{d}}}", .{ if (ix > 0) "," else "", acc.id, countAcc(acc), FIELDS.len }) catch continue; out.appendSlice(ctx.aren, row) catch {}; } task.say(ctx, "{{\"file\":\"{s}\",\"main\":\"{s}\",\"accounts\":[{s}]}}", .{ CF.file, book.main, out.items }); return; }
task.say(ctx, "secrets folder: {s}", .{dir}); if (!book.filez) { task.say(ctx, "no {s} found: create it there ({{\"login\":\"..\",\"pass\":\"..\"}} for one account, or {{\"main\":\"shop1\",\"accs\":[{{\"id\":\"shop1\",\"login\":\"..\",\"pass\":\"..\"}}]}}); fields {s}; fb never prints the values", .{ CF.file, "login, pass, newp, firs, last, mail, birt" }); return; }
for (book.accs) |acc| { var names: std.ArrayList(u8) = .empty; for (FIELDS) |nm| { if (!setOf(acc, nm)) continue; if (names.items.len > 0) names.appendSlice(ctx.aren, ", ") catch {}; names.appendSlice(ctx.aren, nm) catch {}; } task.say(ctx, "{s}{s}: {d} of {d} fields set ({s}); lang={s} caps={d}%", .{ acc.id, if (std.mem.eql(u8, acc.id, book.main)) " [main]" else "", countAcc(acc), FIELDS.len, names.items, if (acc.lang.len > 0) acc.lang else "default", acc.scal }); } task.say(ctx, "{d} account(s), limit {d}; values are never shown", .{ book.accs.len, ctx.conf.acct_maxx_coun }); }
